-- +goose Up
-- Divisions, villages and streets under the 2022 census wards.
-- Divisions come from the 2012 ward boundaries (spatialworks/tanzania) and are
-- blank there for Dodoma, Morogoro, Tabora, Lindi, Singida, Manyara, Shinyanga,
-- Pwani, Simiyu, Geita, Njombe, Iringa, Dar es Salaam and Zanzibar, so those
-- wards stay directly under their council.
-- Villages and streets are the postal mtaa/village list (HackEAC), matched by
-- region, council and ward name. Rural wards get Village, urban wards get Street.
-- shortcut: postal hamlets and Zanzibar villages/streets are not in that list; replace this load when NBS publishes the 2022 village layer.

INSERT INTO geography_types (uuid, name, code, created_at, updated_at)
SELECT gen_random_uuid(), 'Division', 'Division', NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM geography_types WHERE code = 'Division');

INSERT INTO geography_types (uuid, name, code, created_at, updated_at)
SELECT gen_random_uuid(), 'Street', 'Street', NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM geography_types WHERE code = 'Street');

UPDATE geography_types
SET name = 'Village', updated_at = NOW()
WHERE code = 'Village_Mtaa' AND name = 'Village/Mtaa';

