JOIN geographies p ON p.code = v.parent_code;

UPDATE attractions
SET geography_id = (SELECT id FROM geographies WHERE code = '2002'),
    updated_at = NOW()
WHERE name = 'Serengeti National Park';

-- +goose Down
UPDATE attractions
SET geography_id = (SELECT id FROM geographies WHERE code = '02'),
    updated_at = NOW()
WHERE name = 'Serengeti National Park';

DELETE FROM geographies WHERE code LIKE 'VL%' OR code LIKE 'ST%';

UPDATE geographies AS w
SET parent_id = d.parent_id, updated_at = NOW()
FROM geographies AS d
JOIN geography_types AS dt ON dt.id = d.geography_type_id AND dt.code = 'Division'
WHERE w.parent_id = d.id;

DELETE FROM geographies WHERE code LIKE 'DV%';

UPDATE geography_types
SET name = 'Village/Mtaa', updated_at = NOW()
WHERE code = 'Village_Mtaa' AND name = 'Village';

DELETE FROM geography_types
WHERE code IN ('Division', 'Street')
  AND NOT EXISTS (
      SELECT 1 FROM geographies g WHERE g.geography_type_id = geography_types.id
  );
